/**
 * playlists/import — 歌单导入：外部歌单 → 本地匹配 → 入库 + 缺货清单。
 *
 * 定位修正（见 RADIO.md §12）：这个项目是**个人曲库**，电台只是曲库的
 * 一种常驻消费方式。歌单导入是曲库的第一公民功能：用户从网易云 / QQ 音乐 /
 * Spotify / Apple Music 导出歌单（M3U、平台导出 JSON、或直接粘贴
 * 「歌名 - 歌手」文本），导入器做三件事：
 *
 *   1. 解析：识别 M3U / JSON / CSV / 自由文本四种格式（自动嗅探）
 *   2. 匹配：标题归一化 + 歌手辅助校验，关联到本地已有曲目
 *   3. 入库：命中的进歌单；**没命中的进「缺货清单」原样返回** ——
 *      这份清单就是用户的采集待办（去哪找什么歌），是纯本地曲库
 *      最诚实也最有用的输出。
 *
 * 不做平台爬取/破解 —— 只解析用户自己导出的文件。平台的封闭接口是
 * 抓不住的壁垒，用户手里的导出文件才是。
 */
import type { Song } from '@/server/library';

export type ImportedEntry = { title: string; artist: string };

export type ImportResult = {
	format: 'm3u' | 'json' | 'csv' | 'text';
	entries: ImportedEntry[];
	matchedTrackIds: string[];
	matched: { title: string; artist: string; trackId: string }[];
	missing: ImportedEntry[];
};

const normalize = (s: string) =>
	s
		.toLowerCase()
		.replace(/[\s\p{P}\p{S}]+/gu, '');

/** 解析 M3U/M3U8：#EXTINF:duration,Artist - Title 行携带元数据。 */
function parseM3U(text: string): ImportedEntry[] {
	const out: ImportedEntry[] = [];
	let pending: ImportedEntry | null = null;
	for (const raw of text.split(/\r?\n/)) {
		const line = raw.trim();
		if (!line) continue;
		if (line.startsWith('#EXTINF')) {
			const meta = line.slice(line.indexOf(':') + 1);
			const comma = meta.indexOf(',');
			const info = comma >= 0 ? meta.slice(comma + 1) : meta;
			const dash = info.split(/\s[-–—]\s/);
			pending =
				dash.length >= 2
					? { artist: dash[0].trim(), title: dash.slice(1).join(' - ').trim() }
					: { title: info.trim(), artist: '' };
			continue;
		}
		if (line.startsWith('#')) continue;
		// 非注释行 = 资源路径/URL，配合前面的 EXTINF；没有 EXTINF 就从文件名猜
		if (pending) {
			out.push(pending);
			pending = null;
		} else {
			const stem = line.replace(/\/+$/, '').split('/').pop() ?? line;
			const noExt = stem.replace(/\.[a-z0-9]+$/i, '');
			const dash = noExt.split(/\s[-–—]\s/);
			out.push(
				dash.length >= 2
					? { artist: dash[0].trim(), title: dash.slice(1).join(' - ').trim() }
					: { title: noExt.trim(), artist: '' },
			);
		}
	}
	return out;
}

/** 解析 JSON：接受 [{title,artist}] / {playlist:{tracks}} / {songs:[...]} 等常见导出形状。 */
function parseJsonList(text: string): ImportedEntry[] {
	const parsed = JSON.parse(text) as unknown;
	let arr: unknown[] = [];
	if (Array.isArray(parsed)) arr = parsed;
	else if (parsed && typeof parsed === 'object') {
		const obj = parsed as Record<string, unknown>;
		for (const key of ['tracks', 'songs', 'playlist', 'list']) {
			const v = obj[key];
			if (Array.isArray(v)) {
				arr = v;
				break;
			}
			if (v && typeof v === 'object') {
				const inner = (v as Record<string, unknown>)['tracks'];
				if (Array.isArray(inner)) {
					arr = inner;
					break;
				}
			}
		}
	}
	const out: ImportedEntry[] = [];
	for (const item of arr) {
		if (!item || typeof item !== 'object') continue;
		const o = item as Record<string, unknown>;
		const title = String(o.title ?? o.name ?? o.song ?? '').trim();
		const artist = String(o.artist ?? o.singer ?? o.artists ?? '').trim();
		if (title) out.push({ title, artist });
	}
	return out;
}

/** 解析 CSV / 自由文本：每行一条，逗号/短横线分隔「标题,歌手」或「歌手 - 标题」。 */
function parseTextList(text: string): ImportedEntry[] {
	const out: ImportedEntry[] = [];
	for (const raw of text.split(/\r?\n/)) {
		const line = raw.trim();
		if (!line || line.startsWith('#')) continue;
		if (line.includes(',')) {
			const [title, artist] = line.split(',', 2);
			if (title.trim()) out.push({ title: title.trim(), artist: (artist ?? '').trim() });
			continue;
		}
		const dash = line.split(/\s[-–—]\s/);
		if (dash.length >= 2) {
			// 「歌手 - 标题」与「标题 - 歌手」二义：默认后者（国内导出习惯）
			out.push({ artist: dash[0].trim(), title: dash.slice(1).join(' - ').trim() });
		} else {
			out.push({ title: line, artist: '' });
		}
	}
	return out;
}

/** 嗅探格式并解析。 */
export function parseImportText(text: string): { format: ImportResult['format']; entries: ImportedEntry[] } {
	const t = text.trim();
	if (t.startsWith('[') || t.startsWith('{')) {
		try {
			return { format: 'json', entries: parseJsonList(t) };
		} catch {
			/* 掉到文本解析 */
		}
	}
	if (/^#EXTM3U/m.test(t) || /^#EXTINF/m.test(t)) return { format: 'm3u', entries: parseM3U(t) };
	if (t.includes(',')) return { format: 'csv', entries: parseTextList(t) };
	return { format: 'text', entries: parseTextList(t) };
}

/**
 * 本地匹配：标题归一化相等（或标题包含 + 歌手一致）即命中。
 * 返回命中的曲目 id 与缺货清单。
 */
export function matchToLibrary(entries: ImportedEntry[], songs: Song[]): Omit<ImportResult, 'format' | 'entries'> {
	const byTitle = new Map<string, Song[]>();
	for (const s of songs) {
		const k = normalize(s.title);
		const list = byTitle.get(k) ?? [];
		list.push(s);
		byTitle.set(k, list);
	}
	const matched: ImportResult['matched'] = [];
	const matchedTrackIds: string[] = [];
	const missing: ImportedEntry[] = [];

	for (const e of entries) {
		const key = normalize(e.title);
		if (!key) continue;
		const candidates = byTitle.get(key) ?? [];
		const hit =
			candidates.find((c) => !e.artist || normalize(c.artist).includes(normalize(e.artist))) ??
			candidates[0];
		if (hit) {
			if (!matchedTrackIds.includes(hit.id)) {
				matchedTrackIds.push(hit.id);
				matched.push({ title: e.title, artist: e.artist || hit.artist, trackId: hit.id });
			}
		} else {
			missing.push(e);
		}
	}
	return { matchedTrackIds, matched, missing };
}
