/**
 * POST /api/playlists/import — 歌单导入（个人曲库核心功能）。
 *
 * 入参 { name, description?, content }，content 是用户导出的歌单原文
 * （M3U / 平台导出 JSON / CSV / 「歌手 - 标题」逐行文本，格式自动嗅探）。
 *
 * 流程：解析 → 本地匹配 → 命中入库为歌单；未命中原样返回为「缺货清单」。
 * 响应 { matchedTrackIds, matched, missing } —— 缺货清单是采集待办，
 * 也是纯本地曲库最诚实的输出。
 */
import { getSongs } from '@/server/library';
import { appendPlaylist } from '@/server/library/playlists';
import { matchToLibrary, parseImportText } from '@/server/library/playlist-import';
import { ok, fail } from '@/server/http';

export async function POST(request: Request) {
	let body: { name?: unknown; description?: unknown; content?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}
	const content = typeof body.content === 'string' ? body.content : '';
	const name = typeof body.name === 'string' && body.name.trim() ? body.name.trim() : '导入的歌单';
	const description =
		typeof body.description === 'string' ? body.description : '';
	if (!content.trim()) {
		return fail('content is required', 400);
	}

	try {
		const { format, entries } = parseImportText(content);
		if (entries.length === 0) {
			return fail('歌单内容解析为空', 400);
		}
		const songs = await getSongs();
		const result = matchToLibrary(entries, songs);
		const playlist = await appendPlaylist(
			name,
			description || `导入于 ${new Date().toISOString().slice(0, 10)}（${format} 格式，${entries.length} 条）`,
			result.matchedTrackIds,
		);
		return ok({ format, total: entries.length, playlistId: playlist?.id, ...result });
	} catch (err) {
		return fail(err instanceof Error ? err.message : String(err), 500);
	}
}
